package local.voice

/** Routing is a phone policy, not an instruction generated by the small language model. */
object BrainRouting {
    enum class Target { LOCAL, HERMES }
    fun target(text: String, mode: AssistantRequests.Mode, configured: Boolean): Target {
        if (mode == AssistantRequests.Mode.LOCAL) return Target.LOCAL
        if (mode == AssistantRequests.Mode.HERMES) return Target.HERMES
        if (!configured) return Target.LOCAL
        // Commands already parsed by VoiceCommands bypass this policy. Only light conversation
        // needs the small model; open-ended questions/tasks use the configured larger model.
        val small = text.lowercase(java.util.Locale.ROOT).trim().trimEnd('.', '!', '?')
        return if (small in setOf("привет", "здравствуй", "спасибо", "как дела", "доброе утро", "добрый вечер")) Target.LOCAL else Target.HERMES
    }
    fun failed(answer: String, nativeFailure: String? = null): Boolean = nativeFailure != null || !SpokenReply.hasContent(answer) ||
        answer.startsWith("Не удалось получить ответ") ||
        answer.startsWith("Не смог") || answer.startsWith("Не удалось подготовить ответ") ||
        answer.startsWith("Модель не смогла") || answer.startsWith("Локальная модель не смогла")
}
